package info.deltaindices.volumecamera;
import android.Manifest;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.os.*;import android.provider.Settings.Secure;import android.view.View;import android.widget.*;import androidx.activity.result.*;import androidx.activity.result.contract.ActivityResultContracts;import androidx.appcompat.app.AppCompatActivity;import com.google.android.gms.auth.api.identity.*;import com.google.android.gms.common.api.Scope;import java.util.*;
public final class MainActivity extends AppCompatActivity {
 private static final Scope DRIVE_FILE=new Scope("https://www.googleapis.com/auth/drive.file");
 private Switch armed;private EditText interval,folderName;private Spinner presses;private TextView state,driveState,syncCounts;private final Handler refreshHandler=new Handler(Looper.getMainLooper());private final Runnable refreshTask=new Runnable(){public void run(){refresh();refreshHandler.postDelayed(this,1500);}};
 private final ActivityResultLauncher<String[]> permissions=registerForActivityResult(new ActivityResultContracts.RequestMultiplePermissions(),r->refresh());
 private final ActivityResultLauncher<IntentSenderRequest> authorization=registerForActivityResult(new ActivityResultContracts.StartIntentSenderForResult(),result->{if(result.getResultCode()==RESULT_OK&&result.getData()!=null){try{connected(Identity.getAuthorizationClient(this).getAuthorizationResultFromIntent(result.getData()));}catch(Exception e){driveState.setText("Google authorization failed: "+e.getMessage());}}});
 @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(build());requestNeeded();refresh();}@Override protected void onResume(){super.onResume();refreshHandler.post(refreshTask);}@Override protected void onPause(){refreshHandler.removeCallbacks(refreshTask);super.onPause();}
 private View build(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(40,50,40,40);root.setBackgroundColor(Color.rgb(8,17,14));root.addView(text("VOLUME CAMERA",26));root.addView(text("A persistent notification is shown while armed. Triggering opens a visible capture screen; Android shows its camera privacy indicator.",15));armed=new Switch(this);armed.setText("Arm background volume trigger");armed.setTextColor(Color.WHITE);root.addView(armed);state=text("",14);root.addView(state);root.addView(text("Capture interval (seconds, 2–3600)",14));interval=new EditText(this);interval.setInputType(2);interval.setTextColor(Color.WHITE);root.addView(interval);root.addView(text("Volume Up presses within 5 seconds",14));presses=new Spinner(this);presses.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"3","5"}));root.addView(presses);Button save=button("Save and apply");save.setOnClickListener(v->save());root.addView(save);Button access=button("Open Accessibility settings");access.setOnClickListener(v->startActivity(new Intent(android.provider.Settings.ACTION_ACCESSIBILITY_SETTINGS)));root.addView(access);root.addView(text("Google Drive folder name",14));folderName=new EditText(this);folderName.setTextColor(Color.WHITE);root.addView(folderName);Button drive=button("Connect Google Drive account and folder");drive.setOnClickListener(v->connectDrive());root.addView(drive);driveState=text("",13);root.addView(driveState);syncCounts=text("",16);root.addView(syncCounts);Button retry=button("Sync pending pictures now");retry.setOnClickListener(v->{DriveSync.schedule(this);refresh();});root.addView(retry);Button disconnect=button("Disconnect Google Drive");disconnect.setOnClickListener(v->disconnectDrive());root.addView(disconnect);Button test=button("Start / stop capture now");test.setOnClickListener(v->startActivity(new Intent(this,CaptureActivity.class).setAction(CaptureActivity.ACTION_TOGGLE)));root.addView(test);ScrollView scroll=new ScrollView(this);scroll.addView(root);return scroll;}
 private TextView text(String s,int size){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(Color.WHITE);v.setPadding(0,12,0,12);return v;}private Button button(String s){Button b=new Button(this);b.setText(s);return b;}
 private void save(){int seconds;try{seconds=Integer.parseInt(interval.getText().toString());}catch(Exception e){seconds=5;}seconds=Math.max(2,Math.min(3600,seconds));String folder=folderName.getText().toString().trim();if(folder.isEmpty())folder="FastAndroidCamQi";String old=Settings.driveFolder(this);Settings.prefs(this).edit().putBoolean(Settings.ARMED,armed.isChecked()).putInt(Settings.INTERVAL,seconds).putInt(Settings.PRESSES,presses.getSelectedItemPosition()==1?5:3).putString(Settings.DRIVE_FOLDER,folder).apply();if(!old.equals(folder))Settings.prefs(this).edit().remove(Settings.DRIVE_FOLDER_ID).apply();ArmedService.sync(this);refresh();}
 private void connectDrive(){save();AuthorizationRequest request=AuthorizationRequest.builder().setRequestedScopes(Collections.singletonList(DRIVE_FILE)).build();driveState.setText("Opening Google account authorization…");Identity.getAuthorizationClient(this).authorize(request).addOnSuccessListener(result->{if(result.hasResolution())authorization.launch(new IntentSenderRequest.Builder(result.getPendingIntent()).build());else connected(result);}).addOnFailureListener(error->driveState.setText("Google authorization unavailable: "+error.getMessage()));}
 private void connected(AuthorizationResult result){String token=result.getAccessToken();if(token==null||token.isEmpty()){driveState.setText("Google did not return Drive access; try Connect again");return;}Settings.setDriveToken(this,token);Settings.prefs(this).edit().putBoolean(Settings.DRIVE_AUTH_REQUIRED,false).remove(Settings.DRIVE_FOLDER_ID).apply();DriveSync.schedule(this);refresh();}
 private void disconnectDrive(){String token=Settings.driveToken(this);if(token!=null)Identity.getAuthorizationClient(this).clearToken(ClearTokenRequest.builder().setToken(token).build());Settings.clearDriveToken(this);Settings.prefs(this).edit().remove(Settings.DRIVE_FOLDER_ID).putBoolean(Settings.DRIVE_AUTH_REQUIRED,false).apply();refresh();}
 private void requestNeeded(){ArrayList<String> p=new ArrayList<>();if(checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED)p.add(Manifest.permission.CAMERA);if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)p.add(Manifest.permission.RECORD_AUDIO);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)p.add(Manifest.permission.POST_NOTIFICATIONS);if(Build.VERSION.SDK_INT<=28&&checkSelfPermission(Manifest.permission.WRITE_EXTERNAL_STORAGE)!=PackageManager.PERMISSION_GRANTED)p.add(Manifest.permission.WRITE_EXTERNAL_STORAGE);if(!p.isEmpty())permissions.launch(p.toArray(new String[0]));}
 private void refresh(){if(armed==null)return;armed.setChecked(Settings.armed(this));interval.setText(String.valueOf(Settings.interval(this)));presses.setSelection(Settings.presses(this)==5?1:0);if(!folderName.hasFocus())folderName.setText(Settings.driveFolder(this));String enabledServices=Secure.getString(getContentResolver(),Secure.ENABLED_ACCESSIBILITY_SERVICES);boolean enabled=enabledServices!=null&&enabledServices.contains(getPackageName());state.setText(enabled?"Accessibility trigger enabled":"Enable this app in Accessibility settings before using the hardware trigger");boolean connected=Settings.driveToken(this)!=null,reauth=Settings.prefs(this).getBoolean(Settings.DRIVE_AUTH_REQUIRED,false);driveState.setText(reauth?"Reconnect required · pending media are safe on device":connected?"Google Drive connected · folder: "+Settings.driveFolder(this):"Google Drive not connected");android.content.SharedPreferences p=Settings.prefs(this);syncCounts.setText(p.getInt(DriveSync.TAKEN,0)+" pictures taken · "+p.getInt(DriveSync.SYNCED,0)+" pictures synced · "+p.getInt(DriveSync.AUDIO_SYNCED,0)+" audio files synced · "+DriveSync.pending(this)+" media pending · "+p.getInt(DriveSync.FAILED,0)+" failed attempts\n"+p.getString(DriveSync.LAST,"No sync attempted yet"));}
}
